Form.Script:
include "common/Common.js";

// ---------- 직접 호출: 대출 목록 ----------
function btn_search_OnClick(obj)
{
    ds_cond.ClearData();
    ds_cond.AddRow();
    ds_cond.SetColumn(0, "status", cbo_status.Value);

    Transaction("svcLoanList",
                "http://localhost:8080/bank/miplatform/loan/list",
                "ds_cond=ds_cond",
                "ds_loan=ds_loan",
                "",
                "fn_callback");
}

// ---------- 공통 래퍼 호출: 대출 신청 ----------
function btn_apply_OnClick(obj)
{
    ds_apply.ClearData();
    ds_apply.AddRow();
    ds_apply.SetColumn(0, "acctNo", edt_acct.Text);
    ds_apply.SetColumn(0, "principal", edt_principal.Text);
    ds_apply.SetColumn(0, "termMonths", edt_term.Text);

    gfn_transaction("svcLoanApply",
                    "/miplatform/loan/apply",
                    "ds_apply=ds_apply",
                    "",
                    "",
                    "fn_callback");
}

// ---------- 메뉴 변수에서 URL 을 읽어 호출: 승인/거절 ----------
function fn_decide(strApproveYn)
{
    ds_decide.ClearData();
    ds_decide.AddRow();
    ds_decide.SetColumn(0, "loanNo", ds_loan.GetColumn(ds_loan.row, "loanNo"));
    ds_decide.SetColumn(0, "approveYn", strApproveYn);

    var sUrl = gv_svcUrl + gfn_getMenuUrl("LOAN_DECIDE");   // Common.js 의 메뉴 변수에서 결정
    Transaction("svcLoanDecide",
                sUrl,
                "ds_decide=ds_decide",
                "",
                "",
                "fn_callback");
}

function btn_approve_OnClick(obj) { fn_decide("Y"); }
function btn_reject_OnClick(obj)  { fn_decide("N"); }

function fn_callback(strSvcId, nErrorCode, strErrorMsg)
{
    if (gfn_isError(nErrorCode, strErrorMsg)) {
        return;
    }
    if (strSvcId == "svcLoanApply" || strSvcId == "svcLoanDecide") {
        btn_search_OnClick(btn_search);
    }
}
